package app.dailycare;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.*;
public class PlanTest {
 JSONObject state()throws Exception{return new JSONObject("{\"settings\":{\"enabled\":true},\"snoozes\":{},\"groups\":[{\"id\":\"g\",\"name\":\"Morning\",\"members\":[{\"routineId\":\"a\",\"time\":\"08:00\"},{\"routineId\":\"b\",\"time\":\"08:00\"}]}],\"logs\":[],\"routines\":[{\"id\":\"a\",\"name\":\"A\",\"days\":[0,1,2,3,4,5,6],\"times\":[\"08:00\",\"20:00\"]},{\"id\":\"b\",\"name\":\"B\",\"days\":[0,1,2,3,4,5,6],\"times\":[\"08:00\"]}]}");}
 long morning(){Calendar c=Calendar.getInstance();c.set(2026,9,27,7,0,0);c.set(Calendar.MILLISECOND,0);return c.getTimeInMillis();}
 @Test public void groupingAndNoBacklog()throws Exception{JSONArray p=Plan.build(state(),morning());assertEquals(70,p.length());assertEquals("g|2026-10-27|08:00",p.getJSONObject(0).getString("key"));for(int i=0;i<p.length();i++)assertTrue(p.getJSONObject(i).getLong("at")>morning());}
 @Test public void completionSkipUndoAndSnooze()throws Exception{JSONObject s=state();s.getJSONArray("logs").put(new JSONObject().put("key","a|2026-10-27|08:00"));s.getJSONArray("logs").put(new JSONObject().put("key","b|2026-10-27|08:00"));assertEquals(69,Plan.build(s,morning()).length());s.getJSONArray("logs").getJSONObject(0).put("undone","now");assertEquals(70,Plan.build(s,morning()).length());s.getJSONObject("snoozes").put("a|2026-10-27|08:00",morning()+7200000);assertEquals(morning()+7200000,Plan.build(s,morning()).getJSONObject(0).getLong("at"));}
 @Test public void rollingRenewalDisabledAndUserIsolation()throws Exception{JSONObject s=state();JSONArray future=Plan.build(s,morning()+60L*86400000);assertEquals(70,future.length());assertFalse(future.getJSONObject(0).getString("key").contains("2026-10-27"));s.getJSONObject("settings").put("enabled",false);assertEquals(0,Plan.build(s,morning()).length());assertEquals(70,Plan.build(state(),morning()).length());}
 @Test public void archiveAndReminderPreference()throws Exception{JSONObject s=state();s.getJSONArray("routines").getJSONObject(0).put("archived",true);assertEquals(35,Plan.build(s,morning()).length());s.getJSONArray("routines").getJSONObject(1).put("remind",false);assertEquals(0,Plan.build(s,morning()).length());}
}
